import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function invalid() {
  return Object.assign(new Error('Invalid batch'), { code: 'ERR_INVALID_BATCH' });
}

function corrupt(message) {
  return Object.assign(new Error(message), { code: 'ERR_LEDGER_CORRUPT' });
}

function validate(batch) {
  if (!batch || typeof batch !== 'object' || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) throw invalid();
  const entries = [];
  for (const entry of batch.entries) {
    if (!entry || typeof entry !== 'object' || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) throw invalid();
    // Normalize -0 so the in-memory result matches what JSON round-trips to.
    entries.push({ key: entry.key, delta: entry.delta === 0 ? 0 : entry.delta });
  }
  return { id: batch.id, entries };
}

function sameEntries(a, b) {
  return a.length === b.length && a.every((entry, i) => entry.key === b[i].key && entry.delta === b[i].delta);
}

function isSnapshot(value) {
  return value !== null && typeof value === 'object' && Number.isSafeInteger(value.revision) && value.revision >= 0
    && value.balances !== null && typeof value.balances === 'object' && !Array.isArray(value.balances)
    && Array.isArray(value.receipts) && value.receipts.length === value.revision;
}

async function read(io, file) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error && error.code === 'ENOENT') return undefined; throw error; }
  return JSON.parse(text);
}

// Stage the full value in `<name>.tmp`, then atomically replace `<name>.json`.
// A partial or failed staging write never touches the published file.
async function save(io, directory, name, value) {
  const staging = path.join(directory, `${name}.tmp`);
  await io.writeFile(staging, JSON.stringify(value));
  await io.rename(staging, path.join(directory, `${name}.json`));
}

