import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function invalid() {
  return Object.assign(new Error('Invalid batch'), { code: 'ERR_INVALID_BATCH' });
}

function corrupt(message) {
  return Object.assign(new Error(message), { code: 'ERR_LEDGER_CORRUPT' });
}

function validate(batch) {
  if (!batch || typeof batch !== 'object' || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) throw invalid();
  const entries = [];
  for (const entry of batch.entries) {
    if (!entry || typeof entry !== 'object' || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) throw invalid();
    // Normalize -0 so the in-memory result matches what JSON round-trips to.
    entries.push({ key: entry.key, delta: entry.delta === 0 ? 0 : entry.delta });
  }
  return { id: batch.id, entries };
}

function sameEntries(a, b) {
  return a.length === b.length && a.every((entry, i) => entry.key === b[i].key && entry.delta === b[i].delta);
}

function isSnapshot(value) {
  return value !== null && typeof value === 'object' && Number.isSafeInteger(value.revision) && value.revision >= 0
    && value.balances !== null && typeof value.balances === 'object' && !Array.isArray(value.balances)
    && Array.isArray(value.receipts) && value.receipts.length === value.revision;
}

async function read(io, file) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error && error.code === 'ENOENT') return undefined; throw error; }
  return JSON.parse(text);
}

// Stage the full value in `<name>.tmp`, then atomically replace `<name>.json`.
// A partial or failed staging write never touches the published file.
async function save(io, directory, name, value) {
  const staging = path.join(directory, `${name}.tmp`);
  await io.writeFile(staging, JSON.stringify(value));
  await io.rename(staging, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (!error || error.code !== 'ENOENT') throw error; }
}

function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) throw invalid();
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

async function recover(directory, io) {
  await io.mkdir(directory, { recursive: true });
  let state = await read(io, path.join(directory, 'ledger.json'));
  if (state === undefined) state = { revision: 0, balances: {}, receipts: [] };
  else if (!isSnapshot(state)) throw corrupt('ledger.json is not a valid ledger snapshot');

  const pending = await read(io, path.join(directory, 'pending.json'));
  if (pending === undefined) return state;
  const target = pending && pending.snapshot;
  if (!isSnapshot(target) || target.revision < 1) throw corrupt('pending.json is not a valid pending transaction');
  const receipt = target.receipts[target.revision - 1];

  if (state.revision === target.revision - 1 && !state.receipts.some(item => item.id === receipt.id)) {
    // Prepared but not yet published: publish the recorded target snapshot.
    await save(io, directory, 'ledger', target);
    state = target;
  } else if (!(state.revision === target.revision && state.receipts[state.revision - 1]?.id === receipt.id)) {
    throw corrupt('pending.json does not match ledger.json');
  }
  await removePending(io, directory);
  return state;
}

export async function recoverLedger(directory, options = {}) {
  return recover(directory, options?.io ?? fs);
}

export async function commitBatch(directory, batch, options = {}) {
  const io = options?.io ?? fs;
  const checkpoint = options?.checkpoint;
  batch = validate(batch);
  const state = await recover(directory, io);

  const existing = state.receipts.find(item => item.id === batch.id);
  if (existing) {
    if (!Array.isArray(existing.entries) || !sameEntries(existing.entries, batch.entries)) {
      throw Object.assign(new Error('Batch ID already used'), { code: 'ERR_BATCH_CONFLICT' });
    }
    return state;
  }

  const next = apply(state, batch);
  // Once pending.json exists, recovery can publish `next` without the caller.
  await save(io, directory, 'pending', { snapshot: next });
  if (checkpoint) await checkpoint('prepared');
  await save(io, directory, 'ledger', next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, directory);
  if (checkpoint) await checkpoint('complete');
  return next;
}

